                <span>{{ ele.label }}</span>
                <span v-if="ele.label==='飞机号' && ele.value.length>0" class="icon" @click="open(ele.value)" />
                <span v-else-if="ele.label==='游戏输赢'" :class="ele.value.includes('-')?'red':'green'">{{ ele.value }}</span>
