<script>
import TitleLine from './modules/TitleLine'
import { getChildMonthData } from '@/api/user'
export default {
  components: {
    TitleLine
  },
  props: {
    currentValue: {
      type: String,
      default: '哈希一分大小'
    }
  },
  data() {
    return {
      title: '下级业绩',
      showFilter: false,
      currentData: '1',
      recordList: [
      //   {
      //   allcz: '1',
      //   uname: '1',
      //   gamewin: '',
      //   ubotname: '1'
      // }
      ],
      loading: false,
      finished: false,
      refreshing: false,
      pageNum: 1,
      pageSize: 10
    }
  },
  created() {
    this.currentData = this.$route.query.type || '1'
    // this.onLoad()
  },
  methods: {
    open(url) {
      window.open(url)
    },
    // goMore() {
    //   this.$router.push({ path: '/rechargeRecord' })
    // }
    async onLoad() { //, ucode: this.$store.getters.userInfo.ucode
    // pages: this.pageNum,
      const res = await getChildMonthData({ agent: this.$route.query.agent, type: this.currentData, pages: this.pageNum })
      if (this.refreshing) {
        this.recordList = []
        this.refreshing = false
      }
      this.recordList = this.recordList.concat(res.dataList)
      this.loading = false
      this.pageNum++
      if (this.recordList.length >= Number(res.totalrow)) {
        this.finished = true
      }
    },
    onRefresh() {
      // 清空列表数据
      this.finished = false
      this.pageNum = 1
      this.refreshing = true
      // 重新加载数据
      // 将 loading 设置为 true，表示处于加载状态
      this.loading = true
      this.onLoad()
    }
  }

}
</script>
